INSERT INTO reviews (id,target_type,target_id,name,rating,company,profile_href,is_active,is_approved,is_verified,submitted_locale,created_at,updated_at) SELECT '8bb4085b-c564-4dd7-8bc5-a10fc5d4db2d','consultant',@FATMA_CONSULTANT,'K••••',5,'msastro.co','https://msastro.co/advisor/home#comment-77111',1,1,0,'tr','2025-10-30 20:37:28','2025-10-30 20:37:28' FROM DUAL WHERE @FATMA_CONSULTANT IS NOT NULL ON DUPLICATE KEY UPDATE target_id=VALUES(target_id),name=VALUES(name),rating=VALUES(rating),company=VALUES(company),profile_href=VALUES(profile_href),is_active=1,is_approved=1,is_verified=0;
INSERT INTO review_i18n (id,review_id,locale,title,comment) SELECT '871dd1ed-da9b-4177-80b4-54df442a8edc','8bb4085b-c564-4dd7-8bc5-a10fc5d4db2d','tr','🌟 Kariyer Astrolojisi ile Potansiyelini Keşfet!','Fatma Hanım’la yaptığımız görüşmede daha ilk dakikadan itibaren enerjisiyle kendimi çok rahat hissettim. Konuşurken samimiyeti ve içtenliği gerçekten hissediliyor. Yorumları ise inanılmaz derecede isabetli ve gerçekçi. Haritamı o kadar doğru okuyup yorumladı ki anlattıkları birebir beni yansıtıyordu. Belirttiğiniz öngörü tarihlerini mutlaka dikkate alacağım kariyerimde ilerlerken yapmam gerekenleri fark etmemi sağladınız ve bana çok aydınlık bir yol gösterdiniz. Teşekkür ederim.' FROM DUAL WHERE @FATMA_CONSULTANT IS NOT NULL ON DUPLICATE KEY UPDATE title=VALUES(title),comment=VALUES(comment);
