INSERT INTO reviews (id,target_type,target_id,name,rating,company,profile_href,is_active,is_approved,is_verified,submitted_locale,created_at,updated_at) SELECT 'f0fcdb44-3a70-4ca1-8c11-eabd42b6e9d1','consultant',@FATMA_CONSULTANT,'•••••',5,'msastro.co','https://msastro.co/advisor/home#comment-1007',1,1,0,'tr','2024-03-24 09:51:20','2024-03-24 09:51:20' FROM DUAL WHERE @FATMA_CONSULTANT IS NOT NULL ON DUPLICATE KEY UPDATE target_id=VALUES(target_id),name=VALUES(name),rating=VALUES(rating),company=VALUES(company),profile_href=VALUES(profile_href),is_active=1,is_approved=1,is_verified=0;
INSERT INTO review_i18n (id,review_id,locale,title,comment) SELECT 'c86717ce-d600-48bd-87e1-3fc55bf409be','f0fcdb44-3a70-4ca1-8c11-eabd42b6e9d1','tr','✨✨TEK SORU (HORARY ASTROLOJİSİ)✨✨🔮 Sorduğun Soruya Gökyüzü Cevap Veriyor','Ben horary ile Fatma hanımla tanıştım. Hiç bilmiyorum bilmemde astroloji ne demek. Söylediği tarihleri tek tek not ediyorum. Normal fallarda belli noktalarda uymuyor dediğiniz yerler olurken bu horary denilen sistemde kafamda cuk oturuyor. Nedenleriyle beraber. Bunca parayı fallara boşuna dökmüşüm. :(' FROM DUAL WHERE @FATMA_CONSULTANT IS NOT NULL ON DUPLICATE KEY UPDATE title=VALUES(title),comment=VALUES(comment);
