INSERT INTO review_i18n (id,review_id,locale,title,comment) SELECT '0a7b694e-51a0-413d-8006-742961dd03bf','e90269a0-6a3f-4220-8b33-a863f26c0097','tr','✨✨TEK SORU (HORARY ASTROLOJİSİ)✨✨🔮 Sorduğun Soruya Gökyüzü Cevap Veriyor','Gerçekten aşırı derecede mantığıma uydu söyledikleri. Ben ilk kez denedim horary. Ne demek olduğunu bile bilmiyordum. Hep kahve Tarot vs biliyordum ki gündüz tam dinlemedim. Şesi detaylıca dinliyorum.  Şuanki fikrim kahve ve tarotta vakit kaybetmişim hissi uyandı bende.' FROM DUAL WHERE @FATMA_CONSULTANT IS NOT NULL ON DUPLICATE KEY UPDATE title=VALUES(title),comment=VALUES(comment);
